create extension if not exists pgcrypto;
create type public.capsule_status as enum ('sealed','ready','opened');
create type public.email_event_status as enum ('pending','sent','failed');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.capsules (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null check (char_length(title) between 1 and 160), status public.capsule_status not null default 'sealed', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unlock_at timestamptz not null, opened_at timestamptz, deleted_at timestamptz, check (unlock_at > created_at), check ((status = 'opened') = (opened_at is not null)));
create table public.capsule_contents (capsule_id uuid primary key references public.capsules(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, message text not null check (char_length(message) between 1 and 100000), project_name text, website_url text, github_url text, additional_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.capsule_attachments (id uuid primary key default gen_random_uuid(), capsule_id uuid not null references public.capsules(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, type text not null check (type in ('image','file','link')), name text not null, path text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.email_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, capsule_id uuid references public.capsules(id) on delete cascade, email_type text not null check (email_type in ('welcome','capsule_ready','reminder')), provider text not null default 'resend', provider_message_id text, status public.email_event_status not null default 'pending', error_message text, attempts integer not null default 0, sent_at timestamptz, created_at timestamptz not null default now());
create index capsules_user_id_idx on public.capsules(user_id); create index capsules_unlock_idx on public.capsules(unlock_at) where deleted_at is null; create index capsules_status_idx on public.capsules(user_id,status) where deleted_at is null; create index attachments_capsule_idx on public.capsule_attachments(capsule_id); create index email_events_status_idx on public.email_events(status);
create unique index email_events_ready_once on public.email_events(capsule_id,email_type) where email_type='capsule_ready' and status in ('pending','sent');
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at(); create trigger capsules_updated_at before update on public.capsules for each row execute function public.set_updated_at(); create trigger contents_updated_at before update on public.capsule_contents for each row execute function public.set_updated_at();
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.refresh_capsule_status() returns void language sql security definer set search_path=public as $$ update public.capsules set status='ready',updated_at=now() where status='sealed' and unlock_at<=now() and deleted_at is null $$; revoke all on function public.refresh_capsule_status() from public; grant execute on function public.refresh_capsule_status() to service_role;
create or replace function public.get_capsule(capsule_uuid uuid) returns table(id uuid,title text,status public.capsule_status,created_at timestamptz,unlock_at timestamptz,opened_at timestamptz,message text,project_name text,website_url text,github_url text,additional_notes text) language sql security invoker as $$ select c.id,c.title,case when c.unlock_at<=now() and c.status='sealed' then 'ready'::public.capsule_status else c.status end,c.created_at,c.unlock_at,c.opened_at,case when c.unlock_at<=now() then x.message end,case when c.unlock_at<=now() then x.project_name end,case when c.unlock_at<=now() then x.website_url end,case when c.unlock_at<=now() then x.github_url end,case when c.unlock_at<=now() then x.additional_notes end from public.capsules c join public.capsule_contents x on x.capsule_id=c.id where c.id=capsule_uuid and c.user_id=auth.uid() and c.deleted_at is null $$;
create or replace function public.open_capsule(capsule_uuid uuid) returns boolean language plpgsql security definer set search_path=public as $$ begin update public.capsules set status='opened',opened_at=coalesce(opened_at,now()),updated_at=now() where id=capsule_uuid and user_id=auth.uid() and unlock_at<=now() and deleted_at is null; return found; end $$;
alter table public.profiles enable row level security; alter table public.capsules enable row level security; alter table public.capsule_contents enable row level security; alter table public.capsule_attachments enable row level security; alter table public.email_events enable row level security;
create policy "own profile read" on public.profiles for select using (id=auth.uid()); create policy "own profile update" on public.profiles for update using (id=auth.uid()) with check (id=auth.uid()); create policy "own capsules read" on public.capsules for select using (user_id=auth.uid() and deleted_at is null); create policy "own capsules insert" on public.capsules for insert with check (user_id=auth.uid() and status='sealed' and opened_at is null); create policy "own sealed capsules update" on public.capsules for update using (user_id=auth.uid() and status='sealed') with check (user_id=auth.uid() and status='sealed'); create policy "own capsules delete" on public.capsules for delete using (user_id=auth.uid()); create policy "own content insert" on public.capsule_contents for insert with check (user_id=auth.uid()); create policy "own content update" on public.capsule_contents for update using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy "own unlocked content read" on public.capsule_contents for select using (user_id=auth.uid() and exists(select 1 from public.capsules where id=capsule_id and user_id=auth.uid() and unlock_at<=now() and deleted_at is null)); create policy "own attachments" on public.capsule_attachments for all using (user_id=auth.uid()) with check (user_id=auth.uid());
grant usage on schema public to anon,authenticated; grant select,insert,update,delete on public.profiles,public.capsules,public.capsule_contents,public.capsule_attachments to authenticated; grant execute on function public.get_capsule(uuid),public.open_capsule(uuid) to authenticated;
